from boto3 import stubbed_service, service_client
from botocore.exceptions import ClientError

class AWSProxy:
    def __init__(self, region_name):
        self.region_name = region_name
        self.stub = stubbed_service('AWS', region_name=self.region_name)

    def get_resource(self, service, **kwargs):
        return self.stub.get_service(service).get_resource(**kwargs)

    def put_resource(self, service, **kwargs):
        return self.stub.get_service(service).put_resource(**kwargs)

    def delete_resource(self, service, **kwargs):
        return self.stub.get_service(service).delete_resource(**kwargs)

    def get_resource_name(self, service, **kwargs):
        return self.stub.get_service(service).get_resource_name(**kwargs)

    def put_resource_name(self, service, **kwargs):
        return self.stub.get_service(service).put_resource_name(**kwargs)

    def delete_resource_name(self, service, **kwargs):
        return self.stub.get_service(service).delete_resource_name(**kwargs)

    def get_service(self, service):
        return self.stub.get_service(service)

# Usage example
if __name__ == "__main__":
    proxy = AWSProxy('us-west-2')
    # Replace 'username', 'password', and 'access_key' with your actual AWS credentials
    proxy.get_resource('s3', Bucket='my-bucket', Key='file.txt')['ETag'] = 'new-etag'
```

